// En C :
int a = 5;
int b = 3;
int c = a + b;

; Équivalent conceptuel en assembleur :
MOV RAX, 5
MOV RBX, 3
ADD RAX, RBX     ; RAX contient c

// En C :
void calculer() {
    int x = 10;
    int y = 20;
    int somme = x + y;
}

; Équivalent conceptuel en assembleur :
PUSH RBP           ; sauvegarde l'ancienne base de pile
MOV RBP, RSP       ; nouvelle base de pile pour cette fonction
; x est conceptuellement à [RBP-8], y à [RBP-16], somme à [RBP-24]
MOV [RBP-8], 10    ; x = 10
MOV [RBP-16], 20   ; y = 20
MOV RAX, [RBP-8]
ADD RAX, [RBP-16]
MOV [RBP-24], RAX  ; somme = x + y
POP RBP            ; restaure la base de pile de l'appelant

// En C :
if (a > b) {
    max = a;
} else {
    max = b;
}

; Équivalent conceptuel en assembleur :
CMP RAX, RBX        ; compare a (RAX) et b (RBX)
JG a_plus_grand
MOV RCX, RBX        ; max = b
JMP fin_si
a_plus_grand:
MOV RCX, RAX        ; max = a
fin_si:
NOP
